def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find connected objects whose color differs from the common tile/background color.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
