                continue
            # Connect horizontally aligned objects through blank cells only.
            lo, hi = max(r0, s0), min(r1, s1)
            if lo <= hi:
                if c1 < d0:
                    left, right = c1, d0
                elif d1 < c0:
                    left, right = d1, c0
                else:
                    left = right = None
                if left is not None:
                    for y in range(lo, hi+1):
                        for x in range(left+1, right):
                            if grid[y][x] == 0:
                                out[y][x] = color
            # Connect vertically aligned objects through blank cells only.
            lo, hi = max(c0, d0), min(c1, d1)
            if lo <= hi:
                if r1 < s0:
                    top, bottom = r1, s0
                elif s1 < r0:
                    top, bottom = s1, r0
