    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    frame = max((v for v in counts if v != 0), key=lambda v: counts[v])
    other_counts = {v: n for v, n in counts.items() if v not in (0, frame)}
    filler = max(other_counts, key=other_counts.get) if other_counts else None
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, frame, filler) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
